    const dz = p.position.z - cz;
    const dist = Math.sqrt(dx * dx + dz * dz);
    if (dist < 0.2) {
      // Apply a small wobble offset
      const wobbleStrength = (0.2 - dist) * 0.5;
      (p as any)._wobbleTimer = 0.5;
      (p as any)._wobbleStrength = wobbleStrength;
