function wirePanel(name: string, buttons: Record<string, () => void>): void {
  const doc = getDoc(name);
  if (!doc) return;
  for (const [id, handler] of Object.entries(buttons)) {
    const el = doc.getElementById(id);
    if (el) el.addEventListener('click', handler);
  }
}

